rows = rows_of(value('LoadOrder'))
pay = load_json(value('WalletGet'), None)
if not rows or not isinstance(pay, dict):
    fail('Order or payment not found.')
o = rows[0]
oid = to_int(o.get('Id'), 0)
pid = to_int(o.get('PaymentRowId'), 0)
if to_int(pay.get('Id'), 0) != to_int(o.get('ConnectPaymentId'), 0) or pay.get('GrossAmount') != to_int(o.get('TotalCents'), 0) or str(pay.get('Currency') or '').upper() != str(o.get('Currency') or '').upper():
    fail('Wallet payment details do not match this order.')
status = to_int(pay.get('Status'), 0)
raw = q(out(pay))
RELOAD = 'SELECT TOP 1 o.Id, o.Reference, o.Email, o.Name, o.Surname, o.Currency, o.SubtotalCents, o.ShippingCents, o.TaxCents, o.TotalCents, o.Status, o.PaymentStatus, o.FulfillmentStatus, o.PaidAt, o.CreatedAt, o.ShippingAddressJson, p.Id AS PaymentRowId, p.ConnectPaymentId, p.Status AS PaymentRowStatus, p.PaymentUrl, (SELECT i.Title AS [Title], i.VariantTitle AS [VariantTitle], i.Sku AS [Sku], i.ImageUrl AS [ImageUrl], i.Qty AS [Qty], i.UnitPriceCents AS [UnitPriceCents], i.LineTotalCents AS [LineTotalCents] FROM (SELECT TOP 2147483647 * FROM order_items WHERE OrderId = o.Id ORDER BY Id) AS i FOR JSON PATH, INCLUDE_NULL_VALUES) AS ItemsJson FROM orders AS o LEFT JOIN payments AS p ON p.Id = ' + str(pid) + ' WHERE o.Id = ' + str(oid) + ';'
if status == 1:
    return '\n'.join(['SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;', 'CREATE TABLE #ctx (k nvarchar(128) PRIMARY KEY, v bigint);', 'DELETE FROM #ctx;', "UPDATE orders SET Status = 'paid', PaymentStatus = 'paid', PaidAt = SYSUTCDATETIME(), UpdatedAt = SYSUTCDATETIME() WHERE Id = " + str(oid) + " AND PaymentStatus = 'pending';", "INSERT INTO #ctx (k, v) VALUES ('fin', @@ROWCOUNT);", "UPDATE payments SET Status = 'succeeded', PaidAt = SYSUTCDATETIME(), RawJson = " + raw + ', UpdatedAt = SYSUTCDATETIME() WHERE Id = ' + str(pid) + " AND (SELECT v FROM #ctx WHERE k = 'fin') = 1;", 'UPDATE product_variants SET StockQty = GREATEST(0, StockQty - (SELECT COALESCE(SUM(Qty), 0) FROM order_items WHERE OrderId = ' + str(oid) + ' AND VariantId = product_variants.Id)), ReservedQty = GREATEST(0, ReservedQty - (SELECT COALESCE(SUM(Qty), 0) FROM order_items WHERE OrderId = ' + str(oid) + ' AND VariantId = product_variants.Id)), UpdatedAt = SYSUTCDATETIME() WHERE Id IN (SELECT VariantId FROM order_items WHERE OrderId = ' + str(oid) + ") AND (SELECT v FROM #ctx WHERE k = 'fin') = 1 AND EXISTS(SELECT 1 FROM products AS p WHERE p.Id = product_variants.ProductId AND p.TrackInventory = 1);", "INSERT INTO inventory_movements (VariantId, ProductId, Delta, Reason, Reference, Note, CreatedBy) SELECT i.VariantId, i.ProductId, -i.Qty, 'sale', " + q(str(o.get('Reference'))) + ", 'Order paid', 'system' FROM order_items AS i JOIN products AS p ON p.Id = i.ProductId WHERE i.OrderId = " + str(oid) + " AND p.TrackInventory = 1 AND (SELECT v FROM #ctx WHERE k = 'fin') = 1;", "UPDATE carts SET Status = 'converted', UpdatedAt = SYSUTCDATETIME() WHERE Id = (SELECT CartId FROM orders WHERE Id = " + str(oid) + ") AND (SELECT v FROM #ctx WHERE k = 'fin') = 1;", 'DELETE FROM cart_items WHERE CartId = (SELECT CartId FROM orders WHERE Id = ' + str(oid) + ") AND (SELECT v FROM #ctx WHERE k = 'fin') = 1;", 'INSERT INTO order_events (OrderId, Type, Message, DataJson, CreatedBy) SELECT ' + str(oid) + ", 'paid', 'Payment received', " + raw + ", 'system' WHERE (SELECT v FROM #ctx WHERE k = 'fin') = 1;", 'COMMIT TRANSACTION;', RELOAD.replace(' AS ItemsJson FROM orders o LEFT JOIN', " AS ItemsJson, (SELECT v FROM #ctx WHERE k = 'fin') AS JustPaid FROM orders o LEFT JOIN"), 'DROP TABLE IF EXISTS #ctx;'])
if status in (2, 3):
    label = 'failed' if status == 2 else 'expired'
    return '\n'.join(['SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;', 'CREATE TABLE #ctx (k nvarchar(128) PRIMARY KEY, v bigint);', 'DELETE FROM #ctx;', "UPDATE orders SET Status = 'cancelled', PaymentStatus = 'failed', CancelledAt = SYSUTCDATETIME(), UpdatedAt = SYSUTCDATETIME() WHERE Id = " + str(oid) + " AND Status = 'pending';", "INSERT INTO #ctx (k, v) VALUES ('fin', @@ROWCOUNT);", 'UPDATE payments SET Status = ' + q(label) + ', RawJson = ' + raw + ', UpdatedAt = SYSUTCDATETIME() WHERE Id = ' + str(pid) + " AND Status = 'pending';", 'UPDATE product_variants SET ReservedQty = GREATEST(0, ReservedQty - (SELECT COALESCE(SUM(Qty), 0) FROM order_items WHERE OrderId = ' + str(oid) + ' AND VariantId = product_variants.Id)), UpdatedAt = SYSUTCDATETIME() WHERE Id IN (SELECT VariantId FROM order_items WHERE OrderId = ' + str(oid) + ") AND (SELECT v FROM #ctx WHERE k = 'fin') = 1 AND EXISTS(SELECT 1 FROM products AS p WHERE p.Id = product_variants.ProductId AND p.TrackInventory = 1);", 'INSERT INTO order_events (OrderId, Type, Message, DataJson, CreatedBy) SELECT ' + str(oid) + ", 'payment_failed', 'Payment " + label + "; reservation released', " + raw + ", 'system' WHERE (SELECT v FROM #ctx WHERE k = 'fin') = 1;", 'COMMIT TRANSACTION;', RELOAD, 'DROP TABLE IF EXISTS #ctx;'])
return 'UPDATE payments SET RawJson = ' + raw + ', UpdatedAt = SYSUTCDATETIME() WHERE Id = ' + str(pid) + '; ' + RELOAD
